-- Single-use guarded operation. A rerun or any concurrent payload/link change fails before writes.

-- Original draft-import package remains unchanged. See the dated review audit and approved-events.json.

begin isolation level serializable;

set local lock_timeout = '5s';

set local statement_timeout = '30s';

create temporary table timeline_review (slug text primary key, before_row jsonb not null, approved jsonb not null) on commit drop;


create temporary table timeline_review_sources (ref text primary key, source_id uuid not null, source jsonb not null, before_row jsonb) on commit drop;


do $preflight$ begin

if (select count(*) from timeline_review) <> 22 then raise exception 'Review allowlist must contain exactly 22 rows'; end if;

