if (select coalesce(jsonb_agg(to_jsonb(x) order by x.event_id,x.topic_id),'[]'::jsonb) from public.event_topics x join public.historical_events e on e.id=x.event_id join timeline_review r using(slug)) is distinct from '[{"event_id":"8ddb0855-0dde-467f-97c7-698068d0304d","id":"3d4a8b92-85be-47ec-921e-dfe46599e4ba","topic_id":"fd366f7b-db44-4f17-8ad9-770d1a68acd5"},{"event_id":"b0dc9598-f9df-447a-8ef1-91d36d500b2b","id":"97e647ac-7ca6-4a6c-8b9a-b76d125657fe","topic_id":"fd366f7b-db44-4f17-8ad9-770d1a68acd5"},{"event_id":"f3cc785f-8896-42b2-a1f4-0044bd6eef4e","id":"12dd7ece-7e1a-4aa7-8582-6dcf85861b20","topic_id":"fd366f7b-db44-4f17-8ad9-770d1a68acd5"},{"event_id":"fa3cca3c-6c31-40fc-bb80-0ed4bdf9b96b","id":"e5ea813a-3089-4abb-a113-d76c51d18c97","topic_id":"fd366f7b-db44-4f17-8ad9-770d1a68acd5"}]'::jsonb then raise exception 'The reviewed event_topics changed; no publication applied'; end if;

if (select coalesce(jsonb_agg(to_jsonb(x) order by x.event_id,x.location_id),'[]'::jsonb) from public.event_locations x join public.historical_events e on e.id=x.event_id join timeline_review r using(slug)) is distinct from '[{"event_id":"3a6a8ace-c837-4901-9901-8613e71d59d1","is_primary":true,"location_id":"6bda60dd-8fb0-4da9-a2fe-2f74b420ae31","location_role":"Nơi diễn ra cuộc chiến đấu"},{"event_id":"8ddb0855-0dde-467f-97c7-698068d0304d","is_primary":true,"location_id":"6f07accd-5b0c-4e34-9ca4-62c560163b13","location_role":"Nơi lễ kết nạp Việt Nam vào ASEAN diễn ra"},{"event_id":"b0dc9598-f9df-447a-8ef1-91d36d500b2b","is_primary":true,"location_id":"36051ce1-5fce-4f65-b73e-f83f752bc941","location_role":"Nơi đặt trụ sở WTO, nơi Đại hội đồng WTO thông qua việc kết nạp Việt Nam"},{"event_id":"fa3cca3c-6c31-40fc-bb80-0ed4bdf9b96b","is_primary":true,"location_id":"58b08dbb-bdd3-48b2-86b3-af9199fc96bf","location_role":"Nơi Chính phủ Việt Nam ra tuyên bố bình thường hóa"}]'::jsonb then raise exception 'The reviewed event_locations changed; no publication applied'; end if;

if (select coalesce(jsonb_agg(to_jsonb(x) order by x.event_id,x.figure_id),'[]'::jsonb) from public.event_figures x join public.historical_events e on e.id=x.event_id join timeline_review r using(slug)) is distinct from '[]'::jsonb then raise exception 'The reviewed event_figures changed; no publication applied'; end if;

if (select coalesce(jsonb_agg(to_jsonb(x) - 'created_by' - 'updated_by' order by x.id),'[]'::jsonb) from public.media_assets x join public.historical_events e on e.id=x.event_id join timeline_review r using(slug)) is distinct from '[]'::jsonb then raise exception 'The reviewed media changed; no publication applied'; end if;

end $preflight$;


-- Replace only this allowlist’s source associations; preserve all source records and unrelated links.

delete from public.event_sources x using public.historical_events e,timeline_review r where x.event_id=e.id and e.slug=r.slug;


-- Keep existing valid lesson associations and ordering. No lesson identities are invented.

delete from public.sgk_lesson_events x using public.historical_events e,timeline_review r where x.event_id=e.id and e.slug=r.slug and not exists(select 1 from jsonb_array_elements(r.approved->'lessonRefs') ref where ref->>'lessonSlug'=x.lesson_slug and ref->>'sectionId'=x.section_id);


delete from public.event_topics x using public.historical_events e,timeline_review r where x.event_id=e.id and e.slug=r.slug and not exists(select 1 from jsonb_array_elements_text(r.approved->'secondaryTopics') st(slug) join public.curriculum_topics t on t.slug=st.slug where t.id=x.topic_id);


-- Existing four legacy place links were not certified by this bounded review; retain the location records themselves.

delete from public.event_locations x using public.historical_events e,timeline_review r where x.event_id=e.id and e.slug=r.slug;

update public.historical_events e set title=r.approved->>'title',summary=r.approved->>'summary',content=r.approved->>'content',start_year=(r.approved->>'startYear')::integer,end_year=(r.approved->>'endYear')::integer,start_date=(r.approved->>'startDate')::date,end_date=(r.approved->>'endDate')::date,date_text=r.approved->>'dateText',date_precision=r.approved->>'datePrecision',topic_id=t.id from timeline_review r join public.curriculum_topics t on t.slug=r.approved->>'topic' where e.slug=r.slug and e.workflow_status='draft';

-- Respect the existing administrative workflow and its source trigger. No role/policy bypass is installed.

update public.historical_events e set workflow_status='pending_review' from timeline_review r where e.slug=r.slug and e.workflow_status='draft';

update public.historical_events e set workflow_status='published',review_note='Duyệt nguồn theo ủy quyền của chủ dự án ngày 26/10/2026; agent tự đối chiếu nguồn, không phải xác nhận của giáo viên hoặc chứng nhận đúng trang SGK. Phạm vi: mốc và nội dung giới hạn trong hồ sơ timeline-review-2026-10-26.' from timeline_review r where e.slug=r.slug and e.workflow_status='pending_review';

do $verify$ begin

if (select count(*) from public.historical_events e join timeline_review r using(slug) where e.workflow_status='published') <> 22 then raise exception 'Expected exactly 22 approved publications'; end if;

if exists(select 1 from public.historical_events e join timeline_review r using(slug) where not exists(select 1 from public.event_sources s where s.event_id=e.id) or not exists(select 1 from public.sgk_lesson_events l where l.event_id=e.id)) then raise exception 'Approved event lost a required source or lesson link'; end if;

end $verify$;

select jsonb_build_object('reviewed_count',(select count(*) from timeline_review),'published_allowlist',(select jsonb_agg(e.slug order by e.slug) from public.historical_events e join timeline_review r using(slug) where e.workflow_status='published'),'counts',(select jsonb_object_agg(workflow_status,cnt) from(select workflow_status,count(*) cnt from public.historical_events group by workflow_status)c)) as publication;

commit;
