insert into timeline_review values
('viet-nam-gia-nhap-wto-2007','{"content":"## Bối cảnh\r\n\r\nCông cuộc Đổi mới đặt ra yêu cầu mở cửa, hội nhập kinh tế quốc tế. Tháng 1/1995, Việt Nam nộp đơn xin gia nhập Tổ chức Thương mại Thế giới (WTO). Để trở thành thành viên, Việt Nam phải đàm phán với nhiều nước và sửa đổi hệ thống pháp luật cho phù hợp với các quy định của WTO.\r\n\r\n## Diễn biến\r\n\r\n- Việt Nam tiến hành đàm phán song phương với các đối tác và đàm phán đa phương trong suốt hơn 11 năm.\r\n- Ngày 7/11/2006, tại Genève, Đại hội đồng WTO chính thức thông qua việc kết nạp Việt Nam.\r\n- Ngày **11/1/2007**, Việt Nam trở thành **thành viên thứ 150** của WTO.\r\n\r\n## Kết quả\r\n\r\nHàng hóa Việt Nam được tiếp cận thị trường của các nước thành viên với điều kiện bình đẳng hơn; đầu tư nước ngoài tăng mạnh; xuất khẩu tăng trưởng nhanh. Đồng thời, doanh nghiệp trong nước phải đối mặt với sức cạnh tranh lớn hơn.\r\n\r\n## Ý nghĩa\r\n\r\nGia nhập WTO là mốc quan trọng của quá trình hội nhập kinh tế quốc tế, khẳng định kết quả của công cuộc Đổi mới, tạo động lực cho tăng trưởng và cải cách thể chế.\r\n\r\n## Câu chuyện nhỏ\r\n\r\nThứ trưởng Bộ Thương mại **Lương Văn Tự** là Trưởng đoàn đàm phán của Chính phủ trong giai đoạn nước rút. Phiên đàm phán song phương cuối cùng — với Hoa Kỳ — là một trong những phiên khó khăn nhất, kết thúc năm 2006, mở đường cho việc Đại hội đồng WTO thông qua việc kết nạp Việt Nam.\r\n\r\n## Em có biết?\r\n\r\nNhiều mặt hàng quen thuộc với em như điện thoại, quần áo, giày dép, cà phê, gạo… được xuất khẩu đi khắp thế giới nhờ quá trình hội nhập mà WTO là một mốc quan trọng.","created_at":"2026-09-30T04:26:35.426498+00:00","date_precision":"exact","date_text":"11/1/2007","end_date":"2007-01-11","end_year":2007,"id":"b0dc9598-f9df-447a-8ef1-91d36d500b2b","is_featured":false,"review_note":null,"slug":"viet-nam-gia-nhap-wto-2007","start_date":"2007-01-11","start_year":2007,"summary":"Ngày 11/1/2007, sau hơn 11 năm đàm phán, Việt Nam chính thức trở thành thành viên thứ 150 của Tổ chức Thương mại Thế giới (WTO), hội nhập sâu rộng vào nền kinh tế toàn cầu.","title":"Việt Nam gia nhập Tổ chức Thương mại Thế giới (WTO)","topic_id":"11768eb9-d277-4de5-b4d5-4242dba36b61","updated_at":"2026-09-30T04:26:35.426498+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"viet-nam-gia-nhap-wto-2007","title":"Việt Nam gia nhập Tổ chức Thương mại Thế giới (WTO)","summary":"Ngày 11/1/2007, Việt Nam trở thành thành viên thứ 150 của WTO.","content":"## Mốc hội nhập\n\nNgày 11/1/2007, Việt Nam trở thành thành viên thứ 150 của Tổ chức Thương mại Thế giới (WTO). Hồ sơ của WTO ghi nhận đơn xin gia nhập của Việt Nam được tiếp nhận ngày 4/1/1995.\n\n## Gợi ý học tập\n\nĐặt hai mốc trên cạnh nhau để nhận biết quá trình chuẩn bị và thời điểm chính thức trở thành thành viên. Gia nhập WTO là một mốc hội nhập kinh tế quốc tế; để đánh giá tác động đối với xuất khẩu, đầu tư hay từng ngành kinh tế, cần đối chiếu thêm số liệu của thời kỳ tương ứng.","topic":"doi-ngoai-viet-nam","secondaryTopics":["cong-cuoc-doi-moi"],"startYear":2007,"endYear":2007,"startDate":"2007-01-11","endDate":"2007-01-11","dateText":"11/1/2007","datePrecision":"exact","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"10-khai-quat-ve-cong-cuoc-doi-moi","sectionId":"muc-3"},{"lessonSlug":"14-doi-ngoai-tu-nam-1975-den-nay","sectionId":"muc-2"}],"sources":[{"id":"wto-accession","locator":"Opening accession paragraph; Viet Nam timeline, Application received row","scope":"Bounded date, membership/announcement and narrative; editorial reading notes are explicitly interpretive.","publicNote":"Phần giới thiệu xác nhận thành viên thứ 150 ngày 11/1/2007; bảng Viet Nam’s Timeline, dòng Application received ghi 4/1/1995.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"existing-later-a","decision":"approve"}'::jsonb),
('viet-nam-gia-nhap-asean-1995','{"content":"## Bối cảnh\r\n\r\nASEAN được thành lập ngày 8/8/1967. Trong nhiều năm, quan hệ giữa Việt Nam và một số nước ASEAN còn nhiều khác biệt. Từ cuối những năm 1980, khi vấn đề Campuchia được giải quyết và Việt Nam tiến hành Đổi mới, quan hệ Việt Nam – ASEAN cải thiện rõ rệt. Tháng 7/1992, Việt Nam ký Hiệp ước Thân thiện và Hợp tác ở Đông Nam Á và trở thành quan sát viên của ASEAN.\r\n\r\n## Diễn biến\r\n\r\nNgày **28/7/1995**, tại Hội nghị Bộ trưởng Ngoại giao ASEAN lần thứ 28 ở Bandar Seri Begawan (Brunei), lễ kết nạp Việt Nam được tổ chức trọng thể. Việt Nam trở thành **thành viên thứ 7** của ASEAN.\r\n\r\n## Kết quả\r\n\r\nViệt Nam tham gia ngày càng tích cực vào các hoạt động của ASEAN: đăng cai Hội nghị Cấp cao ASEAN lần thứ 6 tại Hà Nội (1998), đảm nhiệm vai trò Chủ tịch ASEAN năm 2010 và năm 2020. Việc gia nhập ASEAN cũng mở đường cho Việt Nam tham gia Khu vực Mậu dịch tự do ASEAN (AFTA).\r\n\r\n## Ý nghĩa\r\n\r\nGia nhập ASEAN đánh dấu bước phát triển mới trong chính sách đối ngoại của Việt Nam: từ đối đầu chuyển sang hợp tác, hội nhập khu vực; góp phần xây dựng Đông Nam Á hòa bình, ổn định và thịnh vượng.\r\n\r\n## Câu chuyện nhỏ\r\n\r\nTại lễ kết nạp, lá cờ Việt Nam được kéo lên bên cạnh cờ của sáu nước thành viên. Chỉ hai mươi năm trước đó, khu vực còn chìm trong chiến tranh; nay các nước cùng ngồi chung một mái nhà.\r\n\r\n## Em có biết?\r\n\r\n- Hiện nay ASEAN có **11 thành viên** (Timor-Leste được kết nạp năm 2025).\r\n- Khẩu hiệu của ASEAN là **\"Một tầm nhìn, một bản sắc, một cộng đồng\"**.","created_at":"2026-09-30T04:26:35.426498+00:00","date_precision":"exact","date_text":"28/7/1995","end_date":"1995-07-28","end_year":1995,"id":"8ddb0855-0dde-467f-97c7-698068d0304d","is_featured":false,"review_note":null,"slug":"viet-nam-gia-nhap-asean-1995","start_date":"1995-07-28","start_year":1995,"summary":"Ngày 28/7/1995, tại Bandar Seri Begawan (Brunei), Việt Nam chính thức trở thành thành viên thứ 7 của Hiệp hội các quốc gia Đông Nam Á (ASEAN).","title":"Việt Nam gia nhập ASEAN","topic_id":"11768eb9-d277-4de5-b4d5-4242dba36b61","updated_at":"2026-09-30T04:26:35.426498+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"viet-nam-gia-nhap-asean-1995","title":"Việt Nam gia nhập ASEAN","summary":"Ngày 28/7/1995, Việt Nam trở thành thành viên thứ bảy của ASEAN.","content":"## Mốc gia nhập\n\nNgày 28/7/1995, Việt Nam trở thành thành viên thứ bảy của Hiệp hội các quốc gia Đông Nam Á (ASEAN), theo tài liệu của Bộ Ngoại giao.\n\n## Gợi ý học tập\n\nĐây là một mốc để tìm hiểu quá trình mở rộng quan hệ đối ngoại và hội nhập khu vực của Việt Nam sau năm 1986. Cụm từ thành viên thứ bảy thể hiện thứ tự gia nhập ở thời điểm năm 1995; khi tìm hiểu cơ cấu ASEAN ở một thời điểm khác, cần đọc tài liệu của thời điểm đó.","topic":"doi-ngoai-viet-nam","secondaryTopics":["cong-cuoc-doi-moi"],"startYear":1995,"endYear":1995,"startDate":"1995-07-28","endDate":"1995-07-28","dateText":"28/7/1995","datePrecision":"exact","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"14-doi-ngoai-tu-nam-1975-den-nay","sectionId":"muc-2"},{"lessonSlug":"4-su-ra-doi-va-phat-trien-cua-asean","sectionId":"muc-2"}],"sources":[{"id":"mofa-asean","locator":"Section I, introduction/history paragraph beginning Khi mới thành lập ASEAN","scope":"Bounded date, membership/announcement and narrative; editorial reading notes are explicitly interpretive.","publicNote":"Mục I – Khái quát, đoạn lịch sử mở rộng thành viên ghi Việt Nam gia nhập ngày 28/7/1995, là thành viên thứ bảy.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"existing-later-a","decision":"approve"}'::jsonb),
('binh-thuong-hoa-quan-he-viet-my-1995','{"content":"## Bối cảnh\r\n\r\nSau năm 1975, Mỹ thi hành chính sách bao vây, cấm vận đối với Việt Nam. Bước vào công cuộc Đổi mới, Việt Nam chủ trương \"muốn là bạn với tất cả các nước\", từng bước phá thế bao vây, cấm vận. Hai bên hợp tác trong việc giải quyết các vấn đề nhân đạo, như tìm kiếm quân nhân Mỹ mất tích trong chiến tranh (MIA). Ngày 3/2/1994, Tổng thống Mỹ B. Clinton tuyên bố bỏ lệnh cấm vận đối với Việt Nam.\r\n\r\n## Diễn biến\r\n\r\nNgày **11/7/1995**, Tổng thống Mỹ B. Clinton tuyên bố bình thường hóa quan hệ ngoại giao với Việt Nam. Ngày **12/7/1995**, Thủ tướng **Võ Văn Kiệt** tuyên bố Việt Nam thiết lập quan hệ ngoại giao với Hoa Kỳ. Tháng 8/1995, hai nước khai trương đại sứ quán tại thủ đô của nhau.\r\n\r\n## Kết quả\r\n\r\nQuan hệ hai nước từng bước phát triển: năm 2000, ký Hiệp định Thương mại song phương; năm 2013, thiết lập quan hệ **Đối tác toàn diện**; năm 2023, nâng lên **Đối tác chiến lược toàn diện**. Hoa Kỳ trở thành một trong những thị trường xuất khẩu lớn nhất của Việt Nam.\r\n\r\n## Ý nghĩa\r\n\r\nBình thường hóa quan hệ với Hoa Kỳ phá bỏ thế bao vây, cấm vận, mở rộng quan hệ đối ngoại, tạo môi trường thuận lợi cho công cuộc Đổi mới và hội nhập quốc tế. Sự kiện thể hiện tinh thần \"gác lại quá khứ, hướng tới tương lai\" của dân tộc Việt Nam.\r\n\r\n## Câu chuyện nhỏ\r\n\r\nNhiều cựu chiến binh của cả hai nước — những người từng ở hai bên chiến tuyến — sau này đã cùng nhau tham gia các chương trình khắc phục hậu quả chiến tranh: rà phá bom mìn, tẩy độc dioxin, tìm kiếm hài cốt liệt sĩ và quân nhân mất tích.\r\n\r\n## Em có biết?\r\n\r\nNăm 1995 là một năm đặc biệt trong đối ngoại của Việt Nam: chỉ trong vòng một tháng, Việt Nam vừa bình thường hóa quan hệ với Hoa Kỳ (tháng 7), vừa gia nhập ASEAN (28/7/1995).","created_at":"2026-09-30T04:26:35.426498+00:00","date_precision":"period","date_text":"11 – 12/7/1995","end_date":"1995-07-12","end_year":1995,"id":"fa3cca3c-6c31-40fc-bb80-0ed4bdf9b96b","is_featured":false,"review_note":null,"slug":"binh-thuong-hoa-quan-he-viet-my-1995","start_date":"1995-07-11","start_year":1995,"summary":"Tháng 7/1995, Việt Nam và Hoa Kỳ tuyên bố bình thường hóa quan hệ ngoại giao, khép lại quá khứ, hướng tới tương lai sau hai thập kỷ kể từ khi chiến tranh kết thúc.","title":"Bình thường hóa quan hệ Việt Nam – Hoa Kỳ","topic_id":"11768eb9-d277-4de5-b4d5-4242dba36b61","updated_at":"2026-09-30T04:26:35.426498+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"binh-thuong-hoa-quan-he-viet-my-1995","title":"Bình thường hóa quan hệ Việt Nam – Hoa Kỳ","summary":"Tháng 7/1995, Việt Nam và Hoa Kỳ tuyên bố bình thường hóa quan hệ ngoại giao. Văn bản Nhà Trắng ghi ngày 11/7 theo thời gian Hoa Kỳ; nguồn Việt Nam ghi mốc 12/7/1995.","content":"## Tuyên bố bình thường hóa\n\nVăn bản Nhà Trắng ngày 11/7/1995 ghi lại tuyên bố của Tổng thống Bill Clinton về bình thường hóa quan hệ ngoại giao với Việt Nam. Đây là ngày theo thời gian tại Hoa Kỳ.\n\nBáo Điện tử Chính phủ ghi mốc bình thường hóa là ngày 12/7/1995 khi nhìn lại quan hệ hai nước.\n\n## Đọc ngày tháng trong nguồn\n\nHai cách ghi ngày cần được đọc cùng bối cảnh của từng nước. Khi so sánh tài liệu, hãy ghi rõ nguồn và địa điểm của tuyên bố. Bình thường hóa quan hệ ngoại giao, dỡ bỏ cấm vận và khai trương đại sứ quán là những mốc khác nhau; mỗi mốc cần được đối chiếu bằng tài liệu riêng.","topic":"doi-ngoai-viet-nam","secondaryTopics":["cong-cuoc-doi-moi"],"startYear":1995,"endYear":1995,"startDate":"1995-07-11","endDate":"1995-07-12","dateText":"11–12/7/1995 (theo cách ghi ngày của hai nước)","datePrecision":"period","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"14-doi-ngoai-tu-nam-1975-den-nay","sectionId":"muc-2"}],"sources":[{"id":"us-normalization","locator":"Release date July 11, 1995; East Room; first substantive announcement paragraph","scope":"Bounded date, membership/announcement and narrative; editorial reading notes are explicitly interpretive.","publicNote":"Văn bản Nhà Trắng đề ngày 11/7/1995, phần mở đầu tuyên bố bình thường hóa quan hệ ngoại giao; ngày theo thời gian Hoa Kỳ.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."},{"id":"vn-normalization","locator":"Opening summary and first body paragraph, 12/7/1995; following paragraph naming both leaders","scope":"Vietnamese source date convention only; no inference that two declarations were simultaneous.","publicNote":"Đoạn mở đầu và đoạn đầu phần nội dung ghi mốc bình thường hóa ngày 12/7/1995 trong cách nhìn lại của nguồn Việt Nam.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"existing-later-a","decision":"approve"}'::jsonb),
('bao-ve-chu-quyen-gac-ma-1988','{"content":"## Bối cảnh\r\n\r\nQuần đảo Trường Sa là một phần lãnh thổ không thể tách rời của Việt Nam. Cuối những năm 1980, tình hình ở Trường Sa trở nên căng thẳng khi lực lượng Trung Quốc chiếm đóng một số bãi đá. Hải quân Việt Nam triển khai lực lượng ra đóng giữ các đảo, bãi đá để bảo vệ chủ quyền.\r\n\r\n## Diễn biến\r\n\r\n- Sáng **14/3/1988**, tại khu vực đảo Gạc Ma, Cô Lin và Len Đao, lực lượng hải quân Trung Quốc tấn công các chiến sĩ và tàu vận tải của Hải quân Việt Nam.\r\n- Tại Gạc Ma, các chiến sĩ công binh và hải quân, phần lớn không có vũ khí nặng, đã đứng thành **\"vòng tròn bất tử\"** quanh lá cờ Tổ quốc để bảo vệ đảo.\r\n- Các tàu vận tải HQ-604 và HQ-605 bị bắn chìm. Tàu HQ-505 lao lên bãi Cô Lin để giữ đảo.\r\n\r\n## Kết quả\r\n\r\n**64 chiến sĩ** hy sinh. Đảo Gạc Ma bị Trung Quốc chiếm giữ, nhưng ta đã giữ được Cô Lin và Len Đao.\r\n\r\n## Ý nghĩa\r\n\r\nSự hy sinh của các chiến sĩ Gạc Ma là biểu tượng của tinh thần sẵn sàng hy sinh vì chủ quyền biển, đảo thiêng liêng của Tổ quốc; nhắc nhở thế hệ hôm nay về trách nhiệm bảo vệ chủ quyền bằng các biện pháp hòa bình, phù hợp luật pháp quốc tế.\r\n\r\n## Câu chuyện nhỏ\r\n\r\nKhi bị bao vây, chiến sĩ **Trần Văn Phương** đã giữ chặt lá cờ Tổ quốc và hô: *\"Thà hy sinh chứ không chịu mất đảo, hãy để cho máu của mình tô thắm lá cờ truyền thống của Quân chủng Hải quân\"*. Anh hy sinh khi mới 23 tuổi và được truy tặng danh hiệu Anh hùng Lực lượng vũ trang nhân dân.\r\n\r\n## Em có biết?\r\n\r\nCon tàu **HQ-505** do thuyền trưởng Vũ Phi Trừ chỉ huy đã chủ động lao lên bãi Cô Lin trong khi đang bị bắn cháy — một quyết định giúp giữ được đảo.\r\n\r\n## Di tích ngày nay\r\n\r\n**Khu tưởng niệm chiến sĩ Gạc Ma** ở Cam Lâm (Khánh Hòa) có tượng đài \"vòng tròn bất tử\" và nhà trưng bày hiện vật.","created_at":"2026-09-30T04:26:35.426498+00:00","date_precision":"exact","date_text":"14/3/1988","end_date":"1988-03-14","end_year":1988,"id":"3a6a8ace-c837-4901-9901-8613e71d59d1","is_featured":false,"review_note":null,"slug":"bao-ve-chu-quyen-gac-ma-1988","start_date":"1988-03-14","start_year":1988,"summary":"Ngày 14/3/1988, các chiến sĩ Hải quân nhân dân Việt Nam đã chiến đấu anh dũng bảo vệ chủ quyền tại đảo Gạc Ma, Cô Lin, Len Đao thuộc quần đảo Trường Sa; 64 chiến sĩ đã hy sinh.","title":"Cuộc chiến đấu bảo vệ chủ quyền ở Gạc Ma","topic_id":"d6f0c6b0-f41a-4662-aa4d-a6bc9dcc8b60","updated_at":"2026-09-30T04:26:35.426498+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"bao-ve-chu-quyen-gac-ma-1988","title":"Bảo vệ chủ quyền tại Gạc Ma năm 1988","topic":"bao-ve-to-quoc-sau-1975","secondaryTopics":[],"startYear":1988,"endYear":1988,"startDate":"1988-03-14","endDate":"1988-03-14","dateText":"14/3/1988","datePrecision":"exact","summary":"Ngày 14/3/1988, 64 cán bộ, chiến sĩ Hải quân Việt Nam hy sinh trong sự kiện tại khu vực Gạc Ma.","content":"## Mốc tưởng niệm\n\nNgày 14/3/1988, 64 cán bộ, chiến sĩ Hải quân Việt Nam hy sinh trong sự kiện tại khu vực Gạc Ma. Ngày và số người hy sinh này được Báo Điện tử Chính phủ và Đài Tiếng nói Việt Nam cùng ghi nhận.\n\n## Gợi ý học tập\n\nMốc tưởng niệm giúp tìm hiểu sự hy sinh của người lính trong nhiệm vụ bảo vệ chủ quyền biển, đảo. Nội dung ở đây tập trung vào ngày và số liệt sĩ được hai nguồn xác nhận. Khi tìm hiểu diễn biến chiến đấu hoặc lời kể của người tham gia, cần đọc thêm tài liệu và kiểm tra xuất xứ của từng chi tiết.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"9-bao-ve-to-quoc-tu-sau-thang-4-1975","sectionId":"muc-3"}],"sources":[{"id":"gacma-bcp","locator":"Opening description of 36th anniversary, 14/3/1988–14/3/2024; paragraph on 64 sailors","scope":"Date and commemoration count only; no combat reconstruction or territorial geometry.","publicNote":"Đoạn mở đầu và đoạn về lễ tưởng niệm xác nhận ngày 14/3/1988 và 64 liệt sĩ.","publicScope":"Xác nhận ngày và số liệt sĩ; không dùng để tái dựng chi tiết tác chiến."},{"id":"gacma-vov","locator":"Paragraph beginning Lịch sử vẫn luôn nhắc nhớ; next paragraph Cuộc chiến ấy, 64 chiến sĩ","scope":"Independent broadcaster corroboration of date/count; retrieved HTTP 200 via direct fetch after web extractor failed.","publicNote":"Hai đoạn bắt đầu bằng “Lịch sử vẫn luôn nhắc nhớ” và “Cuộc chiến ấy” xác nhận ngày 14/3/1988 và 64 chiến sĩ hy sinh.","publicScope":"Xác nhận ngày và số liệt sĩ; không dùng để tái dựng chi tiết tác chiến."}],"batch":"existing-later-b","decision":"approve"}'::jsonb),
('chien-dich-viet-bac-1947','{"content":"## Mốc được chọn\n\nNgày 7/10/1947, quân Pháp mở cuộc tiến công lên Việt Bắc; lực lượng kháng chiến tổ chức chiến đấu bảo vệ căn cứ.\n\n## Phạm vi học tập\n\nMốc này đánh dấu ngày mở cuộc tiến công của Pháp và cuộc chiến đấu bảo vệ căn cứ. Không dùng ngày mở đầu thay cho toàn bộ thời gian của chiến dịch. Các số liệu binh lực và câu chữ có sai lệch trong bản số hóa không được đưa vào bài.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"7/10/1947","end_date":"1947-10-07","end_year":1947,"id":"25d8ac17-8981-4688-8df4-455de9943b5d","is_featured":false,"review_note":null,"slug":"chien-dich-viet-bac-1947","start_date":"1947-10-07","start_year":1947,"summary":"Ngày 7/10/1947, quân Pháp mở cuộc tiến công lên Việt Bắc; lực lượng kháng chiến tổ chức chiến đấu bảo vệ căn cứ.","title":"Mở đầu cuộc chiến đấu bảo vệ Việt Bắc năm 1947","topic_id":"0d2a274a-5c79-4bdb-bb72-099958874989","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"chien-dich-viet-bac-1947","title":"Mở đầu cuộc chiến đấu bảo vệ Việt Bắc năm 1947","topic":"khang-chien-chong-phap","secondaryTopics":[],"startYear":1947,"endYear":1947,"startDate":"1947-10-07","endDate":"1947-10-07","dateText":"7/10/1947","datePrecision":"exact","summary":"Ngày 7/10/1947, quân Pháp mở cuộc tiến công lên Việt Bắc; lực lượng kháng chiến tổ chức chiến đấu bảo vệ căn cứ.","content":"## Mở đầu cuộc chiến đấu\n\nNgày 7/10/1947, quân Pháp mở cuộc tiến công lên Việt Bắc. Lực lượng kháng chiến tổ chức chiến đấu bảo vệ căn cứ.\n\n## Gợi ý học tập\n\nDòng thời gian chọn ngày mở đầu để xác định sự kiện. Khi trình bày cuộc chiến đấu bảo vệ Việt Bắc, hãy phân biệt mốc mở đầu với các diễn biến tiếp theo và kết quả của toàn bộ cuộc chiến đấu. Một ngày được đánh dấu trên timeline không thể thay cho thời gian của cả chiến dịch.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"7-khang-chien-chong-phap","sectionId":"muc-2"}],"sources":[{"id":"viet-bac-1947","locator":"1947 entries: TỪ NGÀY 7-10 ĐẾN NGÀY 22-12; 9-10 and 15-10 entries","scope":"Opening milestone and bounded place description only; no unsupported campaign duration, statistics or coordinates.","publicNote":"Niên biểu năm 1947, mục từ ngày 7/10 đến 22/12 và các mục 9/10, 15/10 về cuộc tiến công lên Việt Bắc.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-1","decision":"approve"}'::jsonb),
('chien-dich-bien-gioi-1950','{"content":"## Mốc được chọn\n\nNgày 16/9/1950, trận Đông Khê mở đầu Chiến dịch Biên giới.\n\n## Phạm vi học tập\n\nĐông Khê là trận mở đầu được nguồn xác định. Đây là một mốc trong chiến dịch; bài không biến ngày mở đầu thành thời gian của toàn chiến dịch, và không đưa giờ tấn công vào trường ngày chính xác.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"16/9/1950","end_date":"1950-09-16","end_year":1950,"id":"a1a21db0-d1a2-45b4-a1c5-e4e5833db14b","is_featured":false,"review_note":null,"slug":"chien-dich-bien-gioi-1950","start_date":"1950-09-16","start_year":1950,"summary":"Ngày 16/9/1950, trận Đông Khê mở đầu Chiến dịch Biên giới.","title":"Mở chiến dịch Biên giới năm 1950","topic_id":"0d2a274a-5c79-4bdb-bb72-099958874989","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"chien-dich-bien-gioi-1950","title":"Mở chiến dịch Biên giới năm 1950","topic":"khang-chien-chong-phap","secondaryTopics":[],"startYear":1950,"endYear":1950,"startDate":"1950-09-16","endDate":"1950-09-16","dateText":"16/9/1950","datePrecision":"exact","summary":"Ngày 16/9/1950, trận Đông Khê mở đầu Chiến dịch Biên giới.","content":"## Mở chiến dịch\n\nNgày 16/9/1950, trận Đông Khê mở đầu Chiến dịch Biên giới. Mốc tiến công Đông Khê được Bảo tàng Lịch sử Quốc gia và bộ Lịch sử Biên niên Đảng Cộng sản Việt Nam ghi nhận.\n\n## Gợi ý học tập\n\nPhân biệt ngày mở đầu chiến dịch với ngày kết thúc trận Đông Khê và thời gian của toàn chiến dịch. Mốc ngày 16/9 trên timeline giúp định vị điểm khởi đầu; khi học diễn biến và kết quả, cần theo dõi thêm các mốc tiếp theo trong nguồn tham khảo.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"7-khang-chien-chong-phap","sectionId":"muc-2"}],"sources":[{"id":"bien-gioi-national-museum","locator":"Paragraph beginning Ngày 16-9-1950, Trung đoàn 174 và Trung đoàn 209","scope":"Opening attack on Đông Khê only; not campaign ending or exact coordinates.","publicNote":"Đoạn bắt đầu bằng “Ngày 16-9-1950” ghi cuộc tiến công cứ điểm Đông Khê.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."},{"id":"viet-bac-1947","locator":"1950 chronology: paragraph beginning Ngày 16-9-1950, quân đội ta đánh Đông Khê, mở chiến dịch Đường số 4","scope":"Corroboration of opening date and Đông Khê identity.","publicNote":"Niên biểu năm 1950, đoạn ghi ngày 16/9/1950 đánh Đông Khê, mở chiến dịch Đường số 4.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-1","decision":"approve"}'::jsonb),
('phong-trao-dong-khoi-1960','{"content":"## Mốc được chọn\n\nNgày 17/1/1960, Đồng khởi nổ ra tại Định Thủy, Phước Hiệp và Bình Khánh, huyện Mỏ Cày, Bến Tre.\n\n## Phạm vi học tập\n\nBài chọn mốc Bến Tre trong phong trào Đồng khởi rộng hơn. Ngày 17/1 không phải ngày đồng loạt khởi đầu của mọi cuộc nổi dậy ở miền Nam.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"17/1/1960","end_date":"1960-01-17","end_year":1960,"id":"8beab3af-b162-445d-8591-f81c169e2f38","is_featured":false,"review_note":null,"slug":"phong-trao-dong-khoi-1960","start_date":"1960-01-17","start_year":1960,"summary":"Ngày 17/1/1960, Đồng khởi nổ ra tại Định Thủy, Phước Hiệp và Bình Khánh, huyện Mỏ Cày, Bến Tre.","title":"Đồng khởi Bến Tre năm 1960","topic_id":"5f3cdada-f98a-41be-99ba-e6ac533c3c90","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"phong-trao-dong-khoi-1960","title":"Đồng khởi Bến Tre năm 1960","topic":"khang-chien-chong-my","secondaryTopics":[],"startYear":1960,"endYear":1960,"startDate":"1960-01-17","endDate":"1960-01-17","dateText":"17/1/1960","datePrecision":"exact","summary":"Ngày 17/1/1960, Đồng khởi nổ ra tại Định Thủy, Phước Hiệp và Bình Khánh, huyện Mỏ Cày, Bến Tre.","content":"## Đồng khởi tại Bến Tre\n\nNgày 17/1/1960, Đồng khởi nổ ra tại ba xã Định Thủy, Phước Hiệp và Bình Khánh, huyện Mỏ Cày, Bến Tre.\n\n## Gợi ý học tập\n\nĐây là mốc tại Bến Tre trong phong trào Đồng khởi rộng hơn. Khi trình bày, hãy phân biệt nơi nổ ra cuộc nổi dậy, sự lan rộng của phong trào và kết quả. Ngày 17/1/1960 không có nghĩa mọi cuộc nổi dậy ở miền Nam đều khởi đầu cùng ngày.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"8-khang-chien-chong-my-cuu-nuoc","sectionId":"muc-1"}],"sources":[{"id":"dong-khoi-1960","locator":"Paragraphs after Đúng theo kế hoạch, ngày 17-1-1960; preceding paragraph naming three communes","scope":"Opening milestone and bounded place description only; no unsupported campaign duration, statistics or coordinates.","publicNote":"Các đoạn về kế hoạch khởi nghĩa và ngày 17/1/1960 nêu ba xã Định Thủy, Phước Hiệp, Bình Khánh ở Bến Tre.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-1","decision":"approve"}'::jsonb),
('hue-gianh-chinh-quyen-1945','{"content":"## Mốc lịch sử\n\nNgày 23/8/1945, nhân dân Huế nổi dậy giành chính quyền.\n\n## Phạm vi\n\nĐây là mốc giành chính quyền ở một đô thị trong Tổng khởi nghĩa tháng Tám. Không dùng ngày này làm ngày khởi nghĩa chung của cả nước.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"23/8/1945","end_date":"1945-08-23","end_year":1945,"id":"45d7c394-5e7f-4c1e-85e2-f1e00eaee503","is_featured":false,"review_note":null,"slug":"hue-gianh-chinh-quyen-1945","start_date":"1945-08-23","start_year":1945,"summary":"Ngày 23/8/1945, nhân dân Huế nổi dậy giành chính quyền.","title":"Huế giành chính quyền năm 1945","topic_id":"e0ce49ab-39b4-447c-95ae-7c280776661a","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"hue-gianh-chinh-quyen-1945","title":"Huế giành chính quyền năm 1945","topic":"cach-mang-thang-tam-1945","secondaryTopics":[],"startYear":1945,"endYear":1945,"startDate":"1945-08-23","endDate":"1945-08-23","dateText":"23/8/1945","datePrecision":"exact","summary":"Ngày 23/8/1945, nhân dân Huế nổi dậy giành chính quyền.","content":"## Mốc giành chính quyền\n\nNgày 23/8/1945, nhân dân Huế nổi dậy giành chính quyền trong Tổng khởi nghĩa tháng Tám.\n\n## Gợi ý học tập\n\nĐặt mốc Huế bên cạnh các mốc giành chính quyền ở Hà Nội và Sài Gòn để theo dõi tiến trình Tổng khởi nghĩa. Khi trình bày, cần ghi rõ ngày và địa phương; ngày giành chính quyền của một đô thị không phải ngày khởi nghĩa chung cho cả nước.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"6-cach-mang-thang-tam-nam-1945","sectionId":"muc-1"}],"sources":[{"id":"august-1945","locator":"Section Giành chính quyền tại Huế 23/8/1945","scope":"City milestone or bounded two-day battle; no crowd counts, anecdotes, exact sites or campaign-wide date substitution.","publicNote":"Các mục giành chính quyền tại Huế ngày 23/8/1945 và Sài Gòn ngày 25/8/1945.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-2","decision":"approve"}'::jsonb),
('sai-gon-gianh-chinh-quyen-1945','{"content":"## Mốc lịch sử\n\nSáng 25/8/1945, lực lượng cách mạng giành chính quyền ở Sài Gòn.\n\n## Phạm vi\n\nĐây là mốc giành chính quyền ở một đô thị trong Tổng khởi nghĩa tháng Tám. Không dùng ngày này làm ngày khởi nghĩa chung của cả nước.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"25/8/1945","end_date":"1945-08-25","end_year":1945,"id":"05aa8f86-1236-45d3-892d-bd3ed13b4bd8","is_featured":false,"review_note":null,"slug":"sai-gon-gianh-chinh-quyen-1945","start_date":"1945-08-25","start_year":1945,"summary":"Sáng 25/8/1945, lực lượng cách mạng giành chính quyền ở Sài Gòn.","title":"Sài Gòn giành chính quyền năm 1945","topic_id":"e0ce49ab-39b4-447c-95ae-7c280776661a","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"sai-gon-gianh-chinh-quyen-1945","title":"Sài Gòn giành chính quyền năm 1945","topic":"cach-mang-thang-tam-1945","secondaryTopics":[],"startYear":1945,"endYear":1945,"startDate":"1945-08-25","endDate":"1945-08-25","dateText":"25/8/1945","datePrecision":"exact","summary":"Ngày 25/8/1945, lực lượng cách mạng giành chính quyền ở Sài Gòn.","content":"## Mốc giành chính quyền\n\nNgày 25/8/1945, lực lượng cách mạng giành chính quyền ở Sài Gòn trong Tổng khởi nghĩa tháng Tám.\n\n## Gợi ý học tập\n\nĐặt mốc Sài Gòn bên cạnh các mốc Hà Nội và Huế để theo dõi tiến trình Tổng khởi nghĩa. Hãy ghi rõ địa phương khi dẫn ngày tháng, đồng thời phân biệt sự kiện giành chính quyền ở một đô thị với tiến trình trên phạm vi cả nước.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"6-cach-mang-thang-tam-nam-1945","sectionId":"muc-1"}],"sources":[{"id":"august-1945","locator":"Section Giành chính quyền tại Sài Gòn, 25/8/1945; paragraph Sáng 25/8","scope":"City milestone or bounded two-day battle; no crowd counts, anecdotes, exact sites or campaign-wide date substitution.","publicNote":"Các mục giành chính quyền tại Huế ngày 23/8/1945 và Sài Gòn ngày 25/8/1945.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-2","decision":"approve"}'::jsonb),
('chien-thang-buon-ma-thuot-1975','{"content":"## Mốc lịch sử\n\nTrong hai ngày 10–11/3/1975, lực lượng tiến công giải phóng thị xã Buôn Ma Thuột, mở ra bước ngoặt của Chiến dịch Tây Nguyên.\n\n## Phạm vi\n\nKhoảng hai ngày là thời gian trận then chốt tại thị xã được bài nguồn nêu; không phải toàn bộ thời gian Chiến dịch Tây Nguyên.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"period","date_text":"10–11/3/1975","end_date":"1975-03-11","end_year":1975,"id":"381ec287-032d-4670-b492-9f5416640ed7","is_featured":false,"review_note":null,"slug":"chien-thang-buon-ma-thuot-1975","start_date":"1975-03-10","start_year":1975,"summary":"Trong hai ngày 10–11/3/1975, lực lượng tiến công giải phóng thị xã Buôn Ma Thuột, mở ra bước ngoặt của Chiến dịch Tây Nguyên.","title":"Trận Buôn Ma Thuột tháng 3/1975","topic_id":"5f3cdada-f98a-41be-99ba-e6ac533c3c90","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"chien-thang-buon-ma-thuot-1975","title":"Trận Buôn Ma Thuột tháng 3/1975","topic":"khang-chien-chong-my","secondaryTopics":[],"startYear":1975,"endYear":1975,"startDate":"1975-03-10","endDate":"1975-03-11","dateText":"10–11/3/1975","datePrecision":"period","summary":"Trong hai ngày 10–11/3/1975, lực lượng tiến công giải phóng thị xã Buôn Ma Thuột, mở ra bước ngoặt của Chiến dịch Tây Nguyên.","content":"## Trận Buôn Ma Thuột\n\nTrong hai ngày 10–11/3/1975, lực lượng tiến công giải phóng thị xã Buôn Ma Thuột, tạo bước ngoặt trong Chiến dịch Tây Nguyên.\n\n## Gợi ý học tập\n\nKhoảng ngày trên dành cho trận đánh tại thị xã Buôn Ma Thuột. Cần phân biệt trận đánh này với toàn bộ Chiến dịch Tây Nguyên và Tổng tiến công mùa Xuân năm 1975. Khi lập bảng diễn biến, nên ghi riêng tên trận đánh, tên chiến dịch và thời gian tương ứng.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"8-khang-chien-chong-my-cuu-nuoc","sectionId":"muc-3"}],"sources":[{"id":"buon-ma-thuot-1975","locator":"Paragraph beginning Từ ngày 10-11/3/1975","scope":"City milestone or bounded two-day battle; no crowd counts, anecdotes, exact sites or campaign-wide date substitution.","publicNote":"Đoạn về trận then chốt mở màn ghi cuộc tiến công giải phóng thị xã Buôn Ma Thuột trong ngày 10–11/3/1975.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-2","decision":"approve"}'::jsonb),
('giai-phong-hue-1975','{"content":"## Mốc lịch sử\n\nNgày 26/3/1975, thành phố Huế được giải phóng.\n\n## Đọc trong Tổng tiến công mùa Xuân\n\nĐây là ngày kết thúc giải phóng một đô thị theo nguồn. Không dùng mốc này làm ngày mở đầu hay toàn bộ thời gian của chiến dịch trên khu vực rộng hơn.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"26/03/1975","end_date":"1975-03-26","end_year":1975,"id":"b02c096d-c02f-4c49-89f9-d09fd2cc10bb","is_featured":false,"review_note":null,"slug":"giai-phong-hue-1975","start_date":"1975-03-26","start_year":1975,"summary":"Ngày 26/3/1975, thành phố Huế được giải phóng.","title":"Giải phóng Huế năm 1975","topic_id":"5f3cdada-f98a-41be-99ba-e6ac533c3c90","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"giai-phong-hue-1975","title":"Giải phóng Huế năm 1975","topic":"khang-chien-chong-my","secondaryTopics":[],"startYear":1975,"endYear":1975,"startDate":"1975-03-26","endDate":"1975-03-26","dateText":"26/3/1975","datePrecision":"exact","summary":"Ngày 26/3/1975, thành phố Huế được giải phóng.","content":"## Mốc giải phóng Huế\n\nNgày 26/3/1975, thành phố Huế được giải phóng. Mốc này được Bảo tàng Lịch sử Quốc gia và Báo Điện tử Chính phủ ghi nhận.\n\n## Gợi ý học tập\n\nĐặt mốc Huế trong tiến trình Tổng tiến công mùa Xuân năm 1975. Đây là ngày giải phóng thành phố; khi học về chiến dịch trên khu vực Trị Thiên, cần phân biệt thời gian của cả chiến dịch với mốc hoàn thành giải phóng một đô thị.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"8-khang-chien-chong-my-cuu-nuoc","sectionId":"muc-3"}],"sources":[{"id":"spring-museum","locator":"Part 3, Tài liệu, hiện vật tiêu biểu: caption list for Huế 26/3 and Đà Nẵng 29/3","scope":"Concluding city milestone only, not campaign start or duration.","publicNote":"Phần 3, danh mục tài liệu và hiện vật tiêu biểu ghi giải phóng Huế ngày 26/3 và làm chủ Đà Nẵng ngày 29/3/1975.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."},{"id":"hue-1975","locator":"Final paragraph of Đợt 2 (21–26/3/1975)","scope":"Independent city milestone corroboration.","publicNote":"Mục Đợt 2, đoạn cuối ghi đến ngày 26/3/1975 giải phóng thành phố Huế.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-3","decision":"approve"}'::jsonb),
('giai-phong-da-nang-1975','{"content":"## Mốc lịch sử\n\nNgày 29/3/1975, lực lượng giải phóng hoàn toàn làm chủ thành phố Đà Nẵng.\n\n## Đọc trong Tổng tiến công mùa Xuân\n\nĐây là ngày kết thúc giải phóng một đô thị theo nguồn. Không dùng mốc này làm ngày mở đầu hay toàn bộ thời gian của chiến dịch trên khu vực rộng hơn.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"29/03/1975","end_date":"1975-03-29","end_year":1975,"id":"f2adbc0d-8f82-43c3-83ad-90a03d661449","is_featured":false,"review_note":null,"slug":"giai-phong-da-nang-1975","start_date":"1975-03-29","start_year":1975,"summary":"Ngày 29/3/1975, lực lượng giải phóng hoàn toàn làm chủ thành phố Đà Nẵng.","title":"Giải phóng Đà Nẵng năm 1975","topic_id":"5f3cdada-f98a-41be-99ba-e6ac533c3c90","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"giai-phong-da-nang-1975","title":"Giải phóng Đà Nẵng năm 1975","topic":"khang-chien-chong-my","secondaryTopics":[],"startYear":1975,"endYear":1975,"startDate":"1975-03-29","endDate":"1975-03-29","dateText":"29/3/1975","datePrecision":"exact","summary":"Ngày 29/3/1975, lực lượng giải phóng hoàn toàn làm chủ thành phố Đà Nẵng.","content":"## Mốc giải phóng Đà Nẵng\n\nNgày 29/3/1975, lực lượng giải phóng hoàn toàn làm chủ thành phố Đà Nẵng.\n\n## Gợi ý học tập\n\nĐặt mốc Đà Nẵng cạnh các mốc Buôn Ma Thuột, Huế và Sài Gòn để theo dõi tiến trình Tổng tiến công mùa Xuân năm 1975. Ngày giải phóng thành phố là một mốc trong tiến trình đó; không dùng riêng ngày này để biểu thị thời gian của toàn bộ chiến dịch hay cuộc Tổng tiến công.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"8-khang-chien-chong-my-cuu-nuoc","sectionId":"muc-3"}],"sources":[{"id":"spring-museum","locator":"Part 3, Tài liệu, hiện vật tiêu biểu: caption list for Huế 26/3 and Đà Nẵng 29/3","scope":"Concluding city milestone only, not campaign start or duration.","publicNote":"Phần 3, danh mục tài liệu và hiện vật tiêu biểu ghi giải phóng Huế ngày 26/3 và làm chủ Đà Nẵng ngày 29/3/1975.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-3","decision":"approve"}'::jsonb),
('phong-trao-dong-du','{"content":"## Mốc lịch sử\n\nTừ năm 1905, Phan Bội Châu vận động thanh niên Việt Nam sang Nhật Bản học tập. Phong trào bị giải tán năm 1908; Phan Bội Châu và Cường Để bị trục xuất khỏi Nhật Bản vào tháng 2/1909.\n\n## Phạm vi và độ chính xác\n\nNguồn đặt tiêu đề 1905–1908 và ghi thêm việc trục xuất năm 1909 trong phần kết. Khoảng năm ở đây bao gồm cả kết cục đó; không gán một ngày chính xác cho cả phong trào.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"period","date_text":"1905–1909 (hoạt động chủ yếu 1905–1908)","end_date":null,"end_year":1909,"id":"a5aa6b8e-b730-4626-93a8-45f175f4ef42","is_featured":false,"review_note":null,"slug":"phong-trao-dong-du","start_date":null,"start_year":1905,"summary":"Từ năm 1905, Phan Bội Châu vận động thanh niên Việt Nam sang Nhật Bản học tập. Phong trào bị giải tán năm 1908; Phan Bội Châu và Cường Để bị trục xuất khỏi Nhật Bản vào tháng 2/1909.","title":"Phong trào Đông Du","topic_id":"11768eb9-d277-4de5-b4d5-4242dba36b61","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"phong-trao-dong-du","title":"Phong trào Đông Du","topic":"doi-ngoai-viet-nam","startYear":1905,"endYear":1909,"startDate":null,"endDate":null,"dateText":"1905–1909 (hoạt động chủ yếu 1905–1908)","datePrecision":"period","summary":"Từ năm 1905, Phan Bội Châu vận động thanh niên Việt Nam sang Nhật Bản học tập. Phong trào bị giải tán năm 1908; Phan Bội Châu và Cường Để bị trục xuất khỏi Nhật Bản vào tháng 2/1909.","secondaryTopics":[],"content":"## Hoạt động của phong trào\n\nTừ năm 1905, Phan Bội Châu vận động thanh niên Việt Nam sang Nhật Bản học tập. Phong trào bị giải tán năm 1908. Tháng 2/1909, Phan Bội Châu và Cường Để bị trục xuất khỏi Nhật Bản.\n\n## Phân biệt hoạt động và kết cục\n\nBảo tàng Lịch sử Quốc gia đặt tên phong trào theo giai đoạn hoạt động 1905–1908 và ghi thêm việc trục xuất năm 1909 trong phần kết. Khoảng năm 1905–1909 trên timeline bao gồm phần kết này. Khi trả lời về thời gian hoạt động chủ yếu của phong trào, cần giữ rõ giai đoạn 1905–1908.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"12-doi-ngoai-dau-the-ki-xx-den-1945","sectionId":"muc-1"}],"sources":[{"id":"dong-du","locator":"Opening Đầu năm 1905; paragraph Những hoạt động...1905 đến 1908; paragraph Tháng 9 năm 1908...Tháng 2 năm 1909","scope":"Bounded movement/month/commemoration claim; conference-wide dates, exact buildings and statistics excluded.","publicNote":"Các đoạn về đầu năm 1905, giải tán tổ chức học sinh tháng 9/1908 và trục xuất Phan Bội Châu, Cường Để tháng 2/1909.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-4","decision":"approve"}'::jsonb),
('nguyen-ai-quoc-dai-hoi-tours-1920','{"content":"## Mốc lịch sử\n\nTháng 12/1920, Nguyễn Ái Quốc tham dự Đại hội Đảng Xã hội Pháp tại Tours và tham gia sáng lập Đảng Cộng sản Pháp.\n\n## Phạm vi và độ chính xác\n\nNgày trong bài được giữ ở mức tháng theo phạm vi chọn lọc. Trường dữ liệu hiện không có enum tháng; dùng approximate và không điền ngày đầu tháng giả định.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"approximate","date_text":"Tháng 12/1920","end_date":null,"end_year":1920,"id":"beccb92e-8524-491d-b8bb-b54abe284c57","is_featured":false,"review_note":null,"slug":"nguyen-ai-quoc-dai-hoi-tours-1920","start_date":null,"start_year":1920,"summary":"Tháng 12/1920, Nguyễn Ái Quốc tham dự Đại hội Đảng Xã hội Pháp tại Tours và tham gia sáng lập Đảng Cộng sản Pháp.","title":"Nguyễn Ái Quốc tại Đại hội Tours","topic_id":"aadb603e-dda0-4c5d-a0aa-eb9974ed8197","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"nguyen-ai-quoc-dai-hoi-tours-1920","title":"Nguyễn Ái Quốc tại Đại hội Tours","topic":"ho-chi-minh","startYear":1920,"endYear":1920,"startDate":null,"endDate":null,"dateText":"Tháng 12/1920","datePrecision":"approximate","summary":"Tháng 12/1920, Nguyễn Ái Quốc tham dự Đại hội Đảng Xã hội Pháp tại Tours và tham gia sáng lập Đảng Cộng sản Pháp.","secondaryTopics":[],"content":"## Đại hội Tours\n\nTháng 12/1920, Nguyễn Ái Quốc tham dự Đại hội Đảng Xã hội Pháp tại thành phố Tours. Tại đại hội, Người bỏ phiếu tán thành Quốc tế III và tham gia sáng lập Đảng Cộng sản Pháp.\n\n## Gợi ý học tập\n\nMốc trên timeline được ghi ở mức tháng để thể hiện phạm vi của nội dung này. Khi học về quá trình hoạt động của Nguyễn Ái Quốc, hãy đặt sự kiện trong tiến trình tìm đường giải phóng dân tộc và đối chiếu trực tiếp đoạn tư liệu về Đại hội Tours trong nguồn tham khảo.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","sectionId":"muc-1"}],"sources":[{"id":"hcm-journey","locator":"Paragraph Đại hội lần thứ XVIII...tại thành phố Tours tháng 12-1920; following paragraph bỏ phiếu tán thành Quốc tế III","scope":"Bounded movement/month/commemoration claim; conference-wide dates, exact buildings and statistics excluded.","publicNote":"Đoạn về Đại hội Đảng Xã hội Pháp tại Tours tháng 12/1920 và đoạn tiếp theo về việc tán thành Quốc tế III, tham gia sáng lập Đảng Cộng sản Pháp.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-4","decision":"approve"}'::jsonb),
('thanh-lap-dang-cong-san-viet-nam-1930','{"content":"## Mốc lịch sử\n\nNgày 3/2/1930 được xác định là Ngày thành lập Đảng Cộng sản Việt Nam. Nguyễn Ái Quốc chủ trì việc hợp nhất các tổ chức cộng sản thành một đảng thống nhất.\n\n## Phạm vi và độ chính xác\n\nMốc 3/2 là ngày thành lập được kỷ niệm, không phải tuyên bố hội nghị chỉ diễn ra trong một ngày. Bài không chốt thời gian toàn hội nghị từ các niên biểu khác nhau.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"3/2/1930 (ngày thành lập được kỷ niệm)","end_date":"1930-02-03","end_year":1930,"id":"dc3f73b9-b31c-4273-830d-ad2e2bb23074","is_featured":false,"review_note":null,"slug":"thanh-lap-dang-cong-san-viet-nam-1930","start_date":"1930-02-03","start_year":1930,"summary":"Ngày 3/2/1930 được xác định là Ngày thành lập Đảng Cộng sản Việt Nam. Nguyễn Ái Quốc chủ trì việc hợp nhất các tổ chức cộng sản thành một đảng thống nhất.","title":"Thành lập Đảng Cộng sản Việt Nam","topic_id":"aadb603e-dda0-4c5d-a0aa-eb9974ed8197","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"thanh-lap-dang-cong-san-viet-nam-1930","title":"Thành lập Đảng Cộng sản Việt Nam","topic":"ho-chi-minh","startYear":1930,"endYear":1930,"startDate":"1930-02-03","endDate":"1930-02-03","dateText":"3/2/1930 (ngày thành lập được kỷ niệm)","datePrecision":"exact","summary":"Ngày 3/2/1930 được xác định là Ngày thành lập Đảng Cộng sản Việt Nam. Nguyễn Ái Quốc chủ trì việc hợp nhất các tổ chức cộng sản thành một đảng thống nhất.","secondaryTopics":[],"content":"## Mốc thành lập\n\nNgày 3/2/1930 được xác định là Ngày thành lập Đảng Cộng sản Việt Nam. Nguyễn Ái Quốc chủ trì việc hợp nhất các tổ chức cộng sản thành một đảng thống nhất.\n\n## Đọc mốc ngày\n\nNgày 3/2 là ngày thành lập được kỷ niệm. Mốc này không có nghĩa toàn bộ hội nghị hợp nhất chỉ diễn ra trong một ngày. Khi trình bày, cần phân biệt ngày thành lập, quá trình chuẩn bị và nội dung của hội nghị.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"15-khai-quat-cuoc-doi-va-su-nghiep-ho-chi-minh","sectionId":"muc-2"}],"sources":[{"id":"cpv-founding","locator":"Paragraph Hội nghị nhất trí...Ngày 3 tháng 2 năm 1930 trở thành Ngày thành lập Đảng Cộng sản Việt Nam","scope":"Bounded movement/month/commemoration claim; conference-wide dates, exact buildings and statistics excluded.","publicNote":"Đoạn về hội nghị hợp nhất và câu xác định ngày 3/2/1930 là Ngày thành lập Đảng Cộng sản Việt Nam.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-4","decision":"approve"}'::jsonb),
('thanh-lap-viet-minh-1941','{"content":"## Mốc lịch sử\n\nNgày 19/5/1941, Mặt trận Việt Nam độc lập đồng minh, gọi tắt là Việt Minh, ra đời để tập hợp các lực lượng tham gia đấu tranh giải phóng dân tộc.\n\n## Đọc nguồn\n\nMốc thành lập tổ chức này được giữ tách biệt với mốc Nguyễn Ái Quốc trở về nước. Hai sự kiện có quan hệ trong tiến trình chuẩn bị cách mạng nhưng có danh tính và ngày riêng.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"19/5/1941","end_date":"1941-05-19","end_year":1941,"id":"675f99d1-f3ab-4c1a-b09a-bb4c7f192c3b","is_featured":false,"review_note":null,"slug":"thanh-lap-viet-minh-1941","start_date":"1941-05-19","start_year":1941,"summary":"Ngày 19/5/1941, Mặt trận Việt Nam độc lập đồng minh, gọi tắt là Việt Minh, ra đời để tập hợp các lực lượng tham gia đấu tranh giải phóng dân tộc.","title":"Thành lập Mặt trận Việt Minh","topic_id":"e0ce49ab-39b4-447c-95ae-7c280776661a","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"thanh-lap-viet-minh-1941","title":"Thành lập Mặt trận Việt Minh","topic":"cach-mang-thang-tam-1945","secondaryTopics":[],"startYear":1941,"endYear":1941,"startDate":"1941-05-19","endDate":"1941-05-19","dateText":"19/5/1941","datePrecision":"exact","summary":"Ngày 19/5/1941, Mặt trận Việt Nam độc lập đồng minh, gọi tắt là Việt Minh, ra đời để tập hợp các lực lượng tham gia đấu tranh giải phóng dân tộc.","content":"## Mặt trận Việt Minh ra đời\n\nNgày 19/5/1941, Mặt trận Việt Nam độc lập đồng minh, gọi tắt là Việt Minh, ra đời để tập hợp các lực lượng tham gia đấu tranh giải phóng dân tộc.\n\n## Gợi ý học tập\n\nPhân biệt mốc thành lập tổ chức với mốc Nguyễn Ái Quốc trở về nước. Hai sự kiện có quan hệ trong quá trình chuẩn bị cách mạng, nhưng có tên gọi và ngày tháng riêng. Khi lập bảng thời gian, hãy ghi thành hai dòng để thể hiện đúng trình tự.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"16-ho-chi-minh-anh-hung-giai-phong-dan-toc","sectionId":"muc-2"}],"sources":[{"id":"thanh-lap-viet-minh-1941","locator":"Paragraphs Hội nghị đã quyết định thành lập Việt Nam độc lập đồng minh and Ngày 19-5-1941","scope":"Date, event identity and bounded summary only; statistics, exact military positions and anecdotes excluded.","publicNote":"Các đoạn về quyết định thành lập Việt Nam độc lập đồng minh và ngày ra đời 19/5/1941.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-5","decision":"approve"}'::jsonb),
('chien-thang-ap-bac-1963','{"content":"## Mốc lịch sử\n\nNgày 2/1/1963, trận Ấp Bắc diễn ra và lực lượng cách mạng giành thắng lợi.\n\n## Đọc nguồn\n\nBài chọn ngày của trận đánh được nguồn nêu. Không dùng một trận đánh để đại diện cho mọi diễn biến hay ngày kết thúc của một chiến lược chiến tranh; không đưa số liệu thương vong chưa được đối chiếu vào bài.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"2/1/1963","end_date":"1963-01-02","end_year":1963,"id":"3a860cd7-1d1a-4248-af58-e32c92f64401","is_featured":false,"review_note":null,"slug":"chien-thang-ap-bac-1963","start_date":"1963-01-02","start_year":1963,"summary":"Ngày 2/1/1963, trận Ấp Bắc diễn ra và lực lượng cách mạng giành thắng lợi.","title":"Chiến thắng Ấp Bắc","topic_id":"5f3cdada-f98a-41be-99ba-e6ac533c3c90","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"chien-thang-ap-bac-1963","title":"Chiến thắng Ấp Bắc","topic":"khang-chien-chong-my","secondaryTopics":[],"startYear":1963,"endYear":1963,"startDate":"1963-01-02","endDate":"1963-01-02","dateText":"2/1/1963","datePrecision":"exact","summary":"Ngày 2/1/1963, trận Ấp Bắc diễn ra và lực lượng cách mạng giành thắng lợi.","content":"## Trận Ấp Bắc\n\nNgày 2/1/1963, trận Ấp Bắc diễn ra và lực lượng cách mạng giành thắng lợi.\n\n## Gợi ý học tập\n\nĐây là mốc ngày của một trận đánh. Khi học về cuộc kháng chiến chống Mỹ, hãy đặt trận Ấp Bắc trong giai đoạn tương ứng, phân biệt diễn biến của trận đánh với diễn biến trên toàn chiến trường. Một trận thắng không đồng nghĩa với việc mọi hoạt động quân sự của đối phương kết thúc ngay trong ngày đó.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"8-khang-chien-chong-my-cuu-nuoc","sectionId":"muc-1"}],"sources":[{"id":"chien-thang-ap-bac-1963","locator":"Title, opening place/date paragraph and paragraph Sáng ngày 2-1-1963","scope":"Date, event identity and bounded summary only; statistics, exact military positions and anecdotes excluded.","publicNote":"Tiêu đề và các đoạn về ngày 2/1/1963, trận đánh tại Ấp Bắc.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-5","decision":"approve"}'::jsonb),
('chien-thang-van-tuong-1965','{"content":"## Mốc lịch sử\n\nNgày 18/8/1965, trận Vạn Tường diễn ra giữa lực lượng giải phóng miền Nam và quân đội Mỹ.\n\n## Đọc nguồn\n\nBài chọn ngày của trận đánh được nguồn nêu. Không dùng một trận đánh để đại diện cho mọi diễn biến hay ngày kết thúc của một chiến lược chiến tranh; không đưa số liệu thương vong chưa được đối chiếu vào bài.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"18/8/1965","end_date":"1965-08-18","end_year":1965,"id":"97c238c2-8959-4f09-9092-d5ffcfacb65a","is_featured":false,"review_note":null,"slug":"chien-thang-van-tuong-1965","start_date":"1965-08-18","start_year":1965,"summary":"Ngày 18/8/1965, trận Vạn Tường diễn ra giữa lực lượng giải phóng miền Nam và quân đội Mỹ.","title":"Chiến thắng Vạn Tường","topic_id":"5f3cdada-f98a-41be-99ba-e6ac533c3c90","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"chien-thang-van-tuong-1965","title":"Chiến thắng Vạn Tường","topic":"khang-chien-chong-my","secondaryTopics":[],"startYear":1965,"endYear":1965,"startDate":"1965-08-18","endDate":"1965-08-18","dateText":"18/8/1965","datePrecision":"exact","summary":"Ngày 18/8/1965, trận Vạn Tường diễn ra giữa lực lượng giải phóng miền Nam và quân đội Mỹ.","content":"## Trận Vạn Tường\n\nNgày 18/8/1965, trận Vạn Tường diễn ra giữa lực lượng giải phóng miền Nam và quân đội Mỹ.\n\n## Gợi ý học tập\n\nĐặt trận Vạn Tường trong tiến trình cuộc kháng chiến chống Mỹ để so sánh với các mốc trước và sau năm 1965. Khi trình bày, cần phân biệt thời gian của một trận đánh với thời gian của cả giai đoạn chiến tranh; kết quả của từng trận cần được đọc trong nguồn tương ứng.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"8-khang-chien-chong-my-cuu-nuoc","sectionId":"muc-2"}],"sources":[{"id":"chien-thang-van-tuong-1965","locator":"Title and opening paragraph naming opposing forces and date","scope":"Date, event identity and bounded summary only; statistics, exact military positions and anecdotes excluded.","publicNote":"Tiêu đề và đoạn mở đầu về trận Vạn Tường ngày 18/8/1965, giữa lực lượng giải phóng miền Nam và quân đội Mỹ.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-5","decision":"approve"}'::jsonb),
('tien-cong-chien-luoc-1972','{"content":"## Mốc lịch sử\n\nNgày 30/3/1972, cuộc tiến công chiến lược bắt đầu, với Quảng Trị là hướng tiến công chủ yếu.\n\n## Phạm vi\n\nBài chọn mốc mở đầu trong tháng 3. Đây là sự kiện khác với cuộc chiến đấu chống tập kích đường không tại Hà Nội và Hải Phòng tháng 12/1972; không gộp hai sự kiện thành một.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"30/3/1972","end_date":"1972-03-30","end_year":1972,"id":"297903c1-fc60-4463-8446-89508f96ced9","is_featured":false,"review_note":null,"slug":"tien-cong-chien-luoc-1972","start_date":"1972-03-30","start_year":1972,"summary":"Ngày 30/3/1972, cuộc tiến công chiến lược bắt đầu, với Quảng Trị là hướng tiến công chủ yếu.","title":"Mở cuộc tiến công chiến lược năm 1972","topic_id":"5f3cdada-f98a-41be-99ba-e6ac533c3c90","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"tien-cong-chien-luoc-1972","title":"Mở cuộc tiến công chiến lược năm 1972","topic":"khang-chien-chong-my","startYear":1972,"endYear":1972,"startDate":"1972-03-30","endDate":"1972-03-30","dateText":"30/3/1972","datePrecision":"exact","summary":"Ngày 30/3/1972, cuộc tiến công chiến lược bắt đầu, với Quảng Trị là hướng tiến công chủ yếu.","sources":[{"id":"strategic-1972","locator":"Paragraph Trưa 30-3-1972...Quảng Trị...phát triển rộng...kéo dài trong năm 1972","scope":"Opening date and main direction only; campaign-wide end dates excluded.","publicNote":"Đoạn bắt đầu bằng “Trưa 30-3-1972” xác định thời điểm mở cuộc tiến công và hướng chủ yếu Quảng Trị.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"secondaryTopics":[],"content":"## Mở cuộc tiến công\n\nNgày 30/3/1972, cuộc tiến công chiến lược bắt đầu, với Quảng Trị là hướng tiến công chủ yếu.\n\n## Gợi ý học tập\n\nTimeline chọn ngày mở đầu cuộc tiến công. Khi tìm hiểu các diễn biến trong năm 1972, hãy phân biệt sự kiện này với các cuộc chiến đấu chống tập kích đường không. Ghi riêng từng sự kiện và thời gian của nó giúp tránh gộp những hoạt động quân sự khác nhau thành một mốc duy nhất.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"8-khang-chien-chong-my-cuu-nuoc","sectionId":"muc-2"}],"batch":"candidate-6","decision":"approve"}'::jsonb),
('nghi-quyet-khoan-10-1988','{"content":"## Mốc lịch sử\n\nNgày 5/4/1988, Bộ Chính trị ban hành Nghị quyết 10 về đổi mới quản lý kinh tế nông nghiệp, xác định vai trò tự chủ của kinh tế hộ.\n\n## Phạm vi\n\nĐây là ngày ban hành một chủ trương. Phạm vi áp dụng và tác động kinh tế không thể được biểu diễn bằng một điểm ban hành trên bản đồ; bài giữ sự kiện không có tọa độ.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"5/4/1988","end_date":"1988-04-05","end_year":1988,"id":"d3e1a510-98fb-4643-b314-5678722dd7fa","is_featured":false,"review_note":null,"slug":"nghi-quyet-khoan-10-1988","start_date":"1988-04-05","start_year":1988,"summary":"Ngày 5/4/1988, Bộ Chính trị ban hành Nghị quyết 10 về đổi mới quản lý kinh tế nông nghiệp, xác định vai trò tự chủ của kinh tế hộ.","title":"Nghị quyết 10 về đổi mới quản lý kinh tế nông nghiệp","topic_id":"fd366f7b-db44-4f17-8ad9-770d1a68acd5","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"nghi-quyet-khoan-10-1988","title":"Nghị quyết 10 về đổi mới quản lý kinh tế nông nghiệp","topic":"cong-cuoc-doi-moi","startYear":1988,"endYear":1988,"startDate":"1988-04-05","endDate":"1988-04-05","dateText":"5/4/1988","datePrecision":"exact","summary":"Ngày 5/4/1988, Bộ Chính trị ban hành Nghị quyết 10 về đổi mới quản lý kinh tế nông nghiệp, xác định vai trò tự chủ của kinh tế hộ.","sources":[{"id":"khoan-10","locator":"Paragraph Trên cơ sở thắng lợi của cơ chế Khoán 100...ngày 5/4/1988...Nghị quyết 10","scope":"Issuing body/date, policy subject and household autonomy only; no aggregate output attribution.","publicNote":"Đoạn về Khoán 100 và Nghị quyết 10 ngày 5/4/1988, vai trò đơn vị kinh tế tự chủ của hộ gia đình.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"secondaryTopics":[],"content":"## Nghị quyết 10\n\nNgày 5/4/1988, Bộ Chính trị ban hành Nghị quyết 10 về đổi mới quản lý kinh tế nông nghiệp. Nghị quyết xác định vai trò tự chủ của kinh tế hộ.\n\n## Gợi ý học tập\n\nĐây là một mốc chủ trương trong quá trình Đổi mới. Khi đánh giá tác động của chính sách, cần phân biệt ngày ban hành với quá trình thực hiện và kết quả ở từng thời kỳ. Các số liệu về sản xuất, thu nhập hay đời sống nông dân cần được dẫn từ tài liệu tương ứng.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"10-khai-quat-ve-cong-cuoc-doi-moi","sectionId":"muc-1"}],"batch":"candidate-6","decision":"approve"}'::jsonb),
('dai-hoi-dang-lan-thu-viii-1996','{"content":"## Mốc lịch sử\n\nĐại hội VIII diễn ra từ ngày 28/6 đến ngày 1/7/1996 tại Hà Nội, đánh giá mười năm Đổi mới và đề ra nhiệm vụ đẩy mạnh công nghiệp hóa, hiện đại hóa.\n\n## Đọc đánh giá mười năm Đổi mới tại thời điểm 1996\n\nBáo cáo Chính trị tại Đại hội VIII đánh giá Việt Nam đã ra khỏi khủng hoảng kinh tế – xã hội, đồng thời lưu ý một số mặt chưa vững chắc. Đây là đánh giá của văn kiện ở thời điểm 1996, không phải bản tổng kết toàn bộ thời kỳ Đổi mới đến hiện nay.\n\n## Một số bài học được văn kiện nêu\n\nVăn kiện nhấn mạnh giữ mục tiêu độc lập dân tộc và chủ nghĩa xã hội; kết hợp đổi mới kinh tế với đổi mới chính trị, lấy đổi mới kinh tế làm trọng tâm; mở rộng hợp tác quốc tế đi đôi với phát huy nguồn lực bên trong.\n\n## Gợi ý đối chiếu\n\nKhi học, phân biệt kết quả được đánh giá trong một thời kỳ, chủ trương tiếp theo và các mốc hội nhập sau đó. Gia nhập WTO hoặc CPTPP là những ví dụ để đối chiếu tiến trình, không tự chứng minh mọi kết quả kinh tế – xã hội.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"period","date_text":"28/6–1/7/1996","end_date":"1996-07-01","end_year":1996,"id":"cce02e62-7cbe-4de9-94cd-d37c2af017f4","is_featured":false,"review_note":null,"slug":"dai-hoi-dang-lan-thu-viii-1996","start_date":"1996-06-28","start_year":1996,"summary":"Đại hội VIII diễn ra từ ngày 28/6 đến ngày 1/7/1996 tại Hà Nội, đánh giá mười năm Đổi mới và đề ra nhiệm vụ đẩy mạnh công nghiệp hóa, hiện đại hóa.","title":"Đại hội đại biểu toàn quốc lần thứ VIII của Đảng","topic_id":"fd366f7b-db44-4f17-8ad9-770d1a68acd5","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"dai-hoi-dang-lan-thu-viii-1996","title":"Đại hội đại biểu toàn quốc lần thứ VIII của Đảng","topic":"cong-cuoc-doi-moi","startYear":1996,"endYear":1996,"startDate":"1996-06-28","endDate":"1996-07-01","dateText":"28/6–1/7/1996","datePrecision":"period","summary":"Đại hội VIII diễn ra từ ngày 28/6 đến ngày 1/7/1996 tại Hà Nội, đánh giá mười năm Đổi mới và đề ra nhiệm vụ đẩy mạnh công nghiệp hóa, hiện đại hóa.","sources":[{"id":"congress-viii","locator":"Opening context and paragraph Trong hoàn cảnh đó...28-6 đến 1-7-1996","scope":"Congress interval/place and context.","publicNote":"Đoạn ghi Đại hội VIII diễn ra từ 28/6 đến 1/7/1996 tại Hà Nội.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."},{"id":"viii-political-report","locator":"Assessment after 10 years, paragraph Nước ta đã ra khỏi khủng hoảng...nhưng một số mặt còn chưa vững chắc; lessons 1, 2 and 5","scope":"Attributed 1996 assessment and bounded lesson examples; not a current all-period statistical assessment.","publicNote":"Phần đánh giá mười năm Đổi mới, đoạn về ra khỏi khủng hoảng nhưng một số mặt chưa vững chắc; các bài học 1, 2 và 5.","publicScope":"Đánh giá và bài học của văn kiện năm 1996; không phải tổng kết đến hiện nay."}],"secondaryTopics":[],"content":"## Mốc lịch sử\n\nĐại hội VIII diễn ra từ ngày 28/6 đến ngày 1/7/1996 tại Hà Nội, đánh giá mười năm Đổi mới và đề ra nhiệm vụ đẩy mạnh công nghiệp hóa, hiện đại hóa.\n\n## Đọc đánh giá mười năm Đổi mới tại thời điểm 1996\n\nBáo cáo Chính trị tại Đại hội VIII đánh giá Việt Nam đã ra khỏi khủng hoảng kinh tế – xã hội, đồng thời lưu ý một số mặt chưa vững chắc. Đây là đánh giá của văn kiện ở thời điểm 1996, không phải bản tổng kết toàn bộ thời kỳ Đổi mới đến hiện nay.\n\n## Một số bài học được văn kiện nêu\n\nVăn kiện nhấn mạnh giữ mục tiêu độc lập dân tộc và chủ nghĩa xã hội; kết hợp đổi mới kinh tế với đổi mới chính trị, lấy đổi mới kinh tế làm trọng tâm; mở rộng hợp tác quốc tế đi đôi với phát huy nguồn lực bên trong.\n\n## Gợi ý đối chiếu\n\nKhi học, phân biệt kết quả được đánh giá trong một thời kỳ, chủ trương tiếp theo và các mốc hội nhập sau đó. Gia nhập WTO hoặc CPTPP là những ví dụ để đối chiếu tiến trình, không tự chứng minh mọi kết quả kinh tế – xã hội.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"10-khai-quat-ve-cong-cuoc-doi-moi","sectionId":"muc-2"},{"lessonSlug":"11-thanh-tuu-va-bai-hoc-cua-cong-cuoc-doi-moi","sectionId":"muc-1"},{"lessonSlug":"11-thanh-tuu-va-bai-hoc-cua-cong-cuoc-doi-moi","sectionId":"muc-2"}],"batch":"candidate-6","decision":"approve"}'::jsonb),
('cptpp-co-hieu-luc-voi-viet-nam-2019','{"content":"## Mốc hội nhập sau năm 2007\n\nCPTPP có hiệu lực đối với Việt Nam từ ngày 14/1/2019. Thông tin Bộ Công Thương công bố ngày 11/1/2019 phân biệt mốc có hiệu lực với ngày Quốc hội phê chuẩn hiệp định là 12/11/2018.\n\n## Cách đọc mốc\n\nĐây là mốc của quá trình hội nhập quốc tế, được gắn ở mức chủ đề với bài Đổi mới và đối ngoại từ sau 1986. Nó không phải ngày một trận đánh, một chuyến đi hay tác động kinh tế xảy ra tại duy nhất một địa điểm; vì vậy không gán tọa độ. Sự có hiệu lực của hiệp định không tự chứng minh mọi kết quả thương mại sau đó.","created_at":"2026-10-25T15:08:35.072145+00:00","date_precision":"exact","date_text":"14/1/2019","end_date":"2019-01-14","end_year":2019,"id":"f3cc785f-8896-42b2-a1f4-0044bd6eef4e","is_featured":false,"review_note":null,"slug":"cptpp-co-hieu-luc-voi-viet-nam-2019","start_date":"2019-01-14","start_year":2019,"summary":"Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP) có hiệu lực đối với Việt Nam từ ngày 14/1/2019.","title":"CPTPP có hiệu lực đối với Việt Nam","topic_id":"11768eb9-d277-4de5-b4d5-4242dba36b61","updated_at":"2026-10-25T15:08:35.072145+00:00","workflow_status":"draft"}'::jsonb,'{"slug":"cptpp-co-hieu-luc-voi-viet-nam-2019","title":"CPTPP có hiệu lực đối với Việt Nam","topic":"doi-ngoai-viet-nam","secondaryTopics":["cong-cuoc-doi-moi"],"startYear":2019,"endYear":2019,"startDate":"2019-01-14","endDate":"2019-01-14","dateText":"14/1/2019","datePrecision":"exact","summary":"Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP) có hiệu lực đối với Việt Nam từ ngày 14/1/2019.","content":"## Mốc hội nhập\n\nHiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP) có hiệu lực đối với Việt Nam từ ngày 14/1/2019. Bộ Công Thương phân biệt mốc này với ngày Quốc hội thông qua nghị quyết phê chuẩn hiệp định và các văn kiện liên quan là 12/11/2018.\n\n## Gợi ý học tập\n\nPhân biệt phê chuẩn hiệp định với thời điểm hiệp định có hiệu lực. Đặt CPTPP cạnh các mốc ASEAN và WTO để tìm hiểu quá trình hội nhập quốc tế của Việt Nam. Khi đánh giá kết quả thương mại sau đó, cần dùng số liệu và tài liệu của giai đoạn tương ứng.","evidence":"verified","workflowStatus":"published","location":null,"media":null,"lessonRefs":[{"lessonSlug":"14-doi-ngoai-tu-nam-1975-den-nay","sectionId":"muc-2"},{"lessonSlug":"10-khai-quat-ve-cong-cuoc-doi-moi","sectionId":"muc-3"}],"sources":[{"id":"cptpp-moit","locator":"Title; paragraph Đối với Việt Nam, Quốc hội đã thông qua...12 tháng 11 năm 2018...14 tháng 01 năm 2019","scope":"Entry-into-force and distinct ratification date only; not trade impact statistics or exact textbook placement.","publicNote":"Đoạn về Việt Nam ghi ngày Quốc hội thông qua nghị quyết phê chuẩn 12/11/2018 và thời điểm có hiệu lực 14/1/2019.","publicScope":"Xác nhận mốc và phạm vi nội dung được dẫn trong bài; gợi ý học tập là phần biên tập."}],"batch":"candidate-7","decision":"approve"}'::jsonb);
