insert into public.sources(id,title,author_org,publisher,url,source_type,citation,accessed_at) select source_id,source->>'title',source->>'institution',source->>'institution',source->>'url','official',(source->>'institution') || '; accessed 2026-10-26. Claim locators are recorded in event_sources and the dated review ledger.',(source->>'accessedAt')::date from timeline_review_sources where before_row is null;
insert into public.event_sources(event_id,source_id,source_note,confidence_note) select e.id,s.source_id,refs.doc->>'publicNote',refs.doc->>'publicScope' from timeline_review r join public.historical_events e using(slug) cross join lateral jsonb_array_elements(r.approved->'sources') refs(doc) join timeline_review_sources s on s.ref=refs.doc->>'id';
insert into public.sgk_lesson_events(lesson_slug,section_id,event_id,sort_order) select ref->>'lessonSlug',ref->>'sectionId',e.id,(ordinality-1)::integer from timeline_review r join public.historical_events e using(slug) cross join lateral jsonb_array_elements(r.approved->'lessonRefs') with ordinality refs(ref,ordinality) on conflict (lesson_slug,section_id,event_id) do nothing;
insert into public.event_topics(event_id,topic_id) select e.id,t.id from timeline_review r join public.historical_events e using(slug) cross join lateral jsonb_array_elements_text(r.approved->'secondaryTopics') st(slug) join public.curriculum_topics t on t.slug=st.slug on conflict(event_id,topic_id) do nothing;
